"use client";

import { useEffect, useState } from "react";

type Role = "teacher" | "student";
type Page = "overview" | "content" | "assignments" | "submissions" | "record" | "tasks" | "insights" | "classroom" | "knowledge" | "ai";
type Chapter = { id: string; name: string; files: number; status: string };
type Material = { id: string; chapterId: string; name: string; type: string; size: string; downloadUrl: string | null };
type Assignment = { id: string; name: string; chapter: string; chapterId: string | null; deadline: string; status: string; submitted: string; description: string };
type Student = { id: string; name: string; initials: string };
type Submission = { id: string; assignment_id: string; student_id: string; content: string; status: string; score: string | null; feedback: string | null; submitted_at: string };
type LearningTask = { id: string; chapterId: string | null; type: "preview" | "material" | "assignment" | "review"; typeLabel: string; title: string; description: string; startAt: string | null; dueAt: string | null; status: string; completedCount: number; totalStudents: number; completed: boolean; record: { task_id: string; status: string; content: string; completed_at: string | null } | null };
type LessonActivity = { id: string; sessionId: string; type: string; prompt: string; options: string[]; status: string; responses: number; distribution: Record<string, number>; respondents?: Record<string, string[]>; myAnswer: string | null };
type LessonData = { session: { id: string; classId: string; chapterId: string | null; startTime: string; endTime: string | null; status: string } | null; activities: LessonActivity[] };
type InsightStudent = { id: string; name: string; initials: string; completionRate: number; assignmentRate: number; activityRate: number; averageScore: number | null; attention: boolean; attentionReason: string };
type LearningEvent = { id: string; studentId: string | null; studentName: string; label: string; eventType: string; objectType: string; objectId: string | null; occurredAt: string };
type InsightData = { class: { previewCompletionRate: number; assignmentCompletionRate: number; activityParticipationRate: number; averageScore: number | null; scoreDistribution: Record<string, number> }; students: InsightStudent[]; events: LearningEvent[] };
type KnowledgeLink = { id: string; objectType: string; objectId: string; label: string };
type KnowledgeEvidence = { type: string; label: string; detail: string; score?: number };
type KnowledgeMastery = { studentId: string; studentName: string; score: number | null; evidenceCount: number; evidence: KnowledgeEvidence[] };
type KnowledgePoint = { id: string; name: string; description: string; chapterId: string | null; chapterName: string; status: string; links: KnowledgeLink[]; mastery: KnowledgeMastery[] };
type KnowledgeData = { course: { id: string; name: string }; points: KnowledgePoint[]; students: Student[] };
type ClassroomData = { class: { id: string; name: string; courseName: string; term: string; joinCode: string; teacherName: string }; chapters: Chapter[]; materials: Material[]; assignments: Assignment[]; students: Student[]; submissions: Submission[]; tasks: LearningTask[] };
type ClassSummary = { id: string; name: string; courseName: string; term: string; joinCode: string; role: string; studentCount: number };
type GradePayload = { submissionId: string; score: string; feedback: string };
type AIDraftQuestion = { id: string; prompt: string; options: string[]; answer: string; reason: string };
type AIDraft = { summary: string; knowledgePoints: string[]; questions: AIDraftQuestion[]; sourceName: string; sourceType: string; status: string; engine: string };
type AIDraftRecord = { id: string; chapterId: string | null; type: "insight" | "activity"; title: string; summary: string; payload: Record<string, unknown>; sourceRefs: Array<{ type: string; id?: string; label: string }>; status: string; createdAt: string; updatedAt: string };
type AIDraftPayload = { suggestions?: string[]; questions?: AIDraftQuestion[]; sourceName?: string };
type PersonalizedQuestion = { id: string; stem: string; options: string[]; answer?: string; explanation?: string; difficulty: string; knowledgePoint: string; source: string };
type PersonalizedDraft = { id: string; chapterId: string | null; studentId: string; studentName: string; chapterName: string; title: string; description: string; questions: PersonalizedQuestion[]; status: string; createdAt: string; updatedAt: string; publishedAt?: string | null; response?: { answers: Record<string, string>; submittedAt?: string | null } | null };
type AuditLog = { id: string; userName: string; action: string; objectType: string; objectId: string | null; detail: string; createdAt: string };

const demoChapters: Chapter[] = [
  { id: "chapter_1", name: "第 1 章 变量与数据类型", files: 3, status: "已发布" },
  { id: "chapter_2", name: "第 2 章 条件判断", files: 2, status: "已发布" },
  { id: "chapter_3", name: "第 3 章 循环结构", files: 3, status: "草稿" },
];
const demoStudents: Student[] = ["张三", "李四", "王五", "赵六", "陈可"].map((name, index) => ({ id: `student_${index + 1}`, name, initials: name.slice(0, 1) }));
const fallbackData: ClassroomData = {
  class: { id: "class_python", name: "Python 基础班", courseName: "Python 程序设计", term: "2026 春季学期", joinCode: "PY2026", teacherName: "王老师" },
  chapters: demoChapters,
  materials: [
    { id: "material_1", chapterId: "chapter_3", name: "循环结构讲义.pdf", type: "PDF", size: "2.4 MB", downloadUrl: null },
    { id: "material_2", chapterId: "chapter_3", name: "循环案例.pptx", type: "PPT", size: "6.8 MB", downloadUrl: null },
    { id: "material_3", chapterId: "chapter_3", name: "课堂练习说明.docx", type: "DOC", size: "1.2 MB", downloadUrl: null },
  ],
  assignments: [
    { id: "assignment_1", name: "变量基础练习", chapter: "第 1 章", chapterId: "chapter_1", deadline: "09-12", status: "已结束", submitted: "36/36", description: "完成变量与数据类型练习。" },
    { id: "assignment_2", name: "条件判断练习", chapter: "第 2 章", chapterId: "chapter_2", deadline: "09-18", status: "进行中", submitted: "28/36", description: "完成条件判断基础练习。" },
    { id: "assignment_3", name: "循环结构练习", chapter: "第 3 章", chapterId: "chapter_3", deadline: "未设置", status: "草稿", submitted: "0/36", description: "请完成三个循环练习，并上传代码或截图。" },
  ],
  students: demoStudents,
  submissions: [],
  tasks: [],
};
const emptyLesson: LessonData = { session: null, activities: [] };
const fallbackInsights: InsightData = { class: { previewCompletionRate: 0, assignmentCompletionRate: 0, activityParticipationRate: 0, averageScore: null, scoreDistribution: {} }, students: [], events: [] };
const fallbackKnowledge: KnowledgeData = { course: { id: "course_python", name: "Python 程序设计" }, points: [], students: [] };

const teacherNav: { id: Page; label: string; icon: string }[] = [
  { id: "overview", label: "班级首页", icon: "⌂" }, { id: "content", label: "课程内容", icon: "▤" },
  { id: "assignments", label: "作业管理", icon: "✓" }, { id: "tasks", label: "学习任务", icon: "◫" }, { id: "classroom", label: "课堂互动", icon: "▣" }, { id: "insights", label: "学情分析", icon: "◒" }, { id: "knowledge", label: "知识点", icon: "◇" }, { id: "ai", label: "AI 助教", icon: "✦" }, { id: "submissions", label: "学生提交", icon: "◌" },
];
const studentNav: { id: Page; label: string; icon: string }[] = [
  { id: "overview", label: "班级首页", icon: "⌂" }, { id: "content", label: "课程内容", icon: "▤" },
  { id: "assignments", label: "我的作业", icon: "✓" }, { id: "tasks", label: "学习任务", icon: "◫" }, { id: "classroom", label: "课堂互动", icon: "▣" }, { id: "knowledge", label: "知识点掌握", icon: "◇" }, { id: "record", label: "学习记录", icon: "◷" },
];

function Badge({ children, tone = "blue" }: { children: React.ReactNode; tone?: "blue" | "green" | "amber" | "gray" }) { return <span className={`status-badge status-${tone}`}>{children}</span>; }
function Metric({ label, value, detail }: { label: string; value: string; detail: string }) { return <div className="metric-card"><p className="eyebrow">{label}</p><p className="metric-value">{value}</p><p className="metric-detail">{detail}</p></div>; }
function SectionTitle({ title, description, action }: { title: string; description?: string; action?: React.ReactNode }) { return <div className="section-title-row"><div><h2>{title}</h2>{description && <p>{description}</p>}</div>{action}</div>; }

export function TeachingApp({ initialRole }: { initialRole?: Role } = {}) {
  const [role, setRole] = useState<Role | null>(initialRole ?? null);
  const [authState, setAuthState] = useState<"checking" | "authenticated" | "anonymous">(initialRole ? "checking" : "anonymous");
  const [page, setPage] = useState<Page>("overview");
  const [data, setData] = useState<ClassroomData>(fallbackData);
  const [classes, setClasses] = useState<ClassSummary[]>([]);
  const [selectedClassId, setSelectedClassId] = useState("");
  const [lesson, setLesson] = useState<LessonData>(emptyLesson);
  const [insights, setInsights] = useState<InsightData>(fallbackInsights);
  const [knowledge, setKnowledge] = useState<KnowledgeData>(fallbackKnowledge);
  const [loading, setLoading] = useState(false);
  const [notice, setNotice] = useState("");
  const [accessState, setAccessState] = useState<"ready" | "no-class">("ready");
  const [selectedAssignmentId, setSelectedAssignmentId] = useState("assignment_3");
  const [modal, setModal] = useState<"assignment" | "chapter" | "join" | "class" | null>(null);
  async function refreshData(requestedClassId = selectedClassId || "") {
    const classResponse = await fetch("/api/classes", { cache: "no-store" });
    const classResult = classResponse.ok ? await classResponse.json() as { classes?: ClassSummary[] } : { classes: [] };
    const classList = classResult.classes ?? [];
    if (classList.length) setClasses(classList);
    const classId = requestedClassId || classList[0]?.id || "";
    const query = classId ? `?classId=${encodeURIComponent(classId)}` : "";
    const response = await fetch(`/api/classroom${query}`, { cache: "no-store" });
    if (!response.ok) { const result = await response.json().catch(() => null) as { error?: string } | null; const error = new Error(result?.error || "班级数据同步失败，请稍后重试。"); (error as Error & { code?: string }).code = response.status === 403 ? "no_class" : "classroom_fetch_failed"; throw error; }
    const next = await response.json() as ClassroomData;
    setSelectedClassId(next.class.id);
    setAccessState("ready");
    const taskResponse = await fetch(`/api/tasks?classId=${encodeURIComponent(next.class.id)}`, { cache: "no-store" });
    const tasks = taskResponse.ok ? (await taskResponse.json() as { tasks?: LearningTask[] }).tasks ?? [] : [];
    const lessonResponse = await fetch(`/api/lessons?classId=${encodeURIComponent(next.class.id)}`, { cache: "no-store" });
    const nextLesson = lessonResponse.ok ? await lessonResponse.json() as LessonData : emptyLesson;
    const insightResponse = await fetch(`/api/insights?classId=${encodeURIComponent(next.class.id)}`, { cache: "no-store" });
    const nextInsights = insightResponse.ok ? await insightResponse.json() as InsightData : fallbackInsights;
    const knowledgeResponse = await fetch(`/api/knowledge?classId=${encodeURIComponent(next.class.id)}`, { cache: "no-store" });
    const nextKnowledge = knowledgeResponse.ok ? await knowledgeResponse.json() as KnowledgeData : fallbackKnowledge;
    setData({ ...next, tasks }); setLesson(nextLesson); setInsights(nextInsights); setKnowledge(nextKnowledge);
    if (!next.assignments.some((item) => item.id === selectedAssignmentId) && next.assignments[0]) setSelectedAssignmentId(next.assignments[0].id);
  }
  useEffect(() => { let cancelled = false; const demoParam = new URLSearchParams(window.location.search).get("demo"); if (initialRole && demoParam !== initialRole) document.cookie = "demo-role=; path=/; max-age=0"; fetch("/api/auth/session", { cache: "no-store" }).then(async (response) => { const result = await response.json().catch(() => null) as { authenticated?: boolean; user?: { role?: Role } } | null; if (cancelled) return; if (response.ok && result?.authenticated) { setAuthState("authenticated"); if (!initialRole && result.user?.role) setRole(result.user.role); } else setAuthState("anonymous"); }).catch(() => { if (!cancelled) setAuthState("anonymous"); }); return () => { cancelled = true; }; }, [initialRole]);
  useEffect(() => { if (!role || authState !== "authenticated") return; refreshData().catch((error) => { if (error instanceof Error && (error as Error & { code?: string }).code === "no_class") setAccessState("no-class"); setNotice(error instanceof Error ? error.message : "班级数据同步失败，请稍后重试。"); }).finally(() => setLoading(false)); }, [role, authState]);
  if (initialRole && authState === "checking") return <AuthLoadingScreen />;
  if (initialRole && authState === "anonymous") return <LoginScreen onLogin={(nextRole) => { document.cookie = `demo-role=${nextRole}; path=/; max-age=1800`; window.location.replace(`${nextRole === "teacher" ? "/teacher" : "/student"}?demo=${nextRole}`); }} />;
  if (role && authState === "authenticated" && accessState === "no-class") return <NoClassScreen role={role} onDemo={(nextRole) => { document.cookie = `demo-role=${nextRole}; path=/; max-age=1800`; window.location.replace(`${nextRole === "teacher" ? "/teacher" : "/student"}?demo=${nextRole}`); }} />;
  if (!role) return <LoginScreen onLogin={(nextRole) => { document.cookie = `demo-role=${nextRole}; path=/; max-age=1800`; window.location.replace(`${nextRole === "teacher" ? "/teacher" : "/student"}?demo=${nextRole}`); }} />;
  const nav = role === "teacher" ? teacherNav : studentNav;
  const switchRole = (nextRole: Role) => { document.cookie = `demo-role=${nextRole}; path=/; max-age=1800`; window.location.replace(`${nextRole === "teacher" ? "/teacher" : "/student"}?demo=${nextRole}`); };
  const createAssignment = async (payload: { name: string; chapterId: string; description: string; deadline: string }) => { try { const response = await fetch("/api/assignments", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) }); if (!response.ok) throw new Error("create_failed"); const result = await response.json() as { assignment?: { id: string } }; const chapter = data.chapters.find((item) => item.id === payload.chapterId); const assignment: Assignment = { id: result.assignment?.id ?? `assignment_${Date.now()}`, name: payload.name, chapter: chapter?.name ?? "未分类", chapterId: payload.chapterId, deadline: payload.deadline || "未设置", status: "草稿", submitted: `0/${data.students.length}`, description: payload.description || "请完成本章节练习。" }; setData((current) => ({ ...current, assignments: [assignment, ...current.assignments] })); setSelectedAssignmentId(assignment.id); setModal(null); setNotice("作业已保存，可以继续编辑或发布。"); } catch { setNotice("保存失败，请稍后重试。"); } };
  const addChapter = async (name: string) => { if ((window as Window & { __qktCreateClass?: boolean }).__qktCreateClass) { const courseName = (document.getElementById("chapter-course-name") as HTMLInputElement | null)?.value.trim() || name; (window as Window & { __qktCreateClass?: boolean }).__qktCreateClass = false; await createClassFromForm(name, courseName); return; } try { const response = await fetch("/api/chapters", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ name }) }); const result = await response.json().catch(() => null) as { error?: string } | null; if (!response.ok) throw new Error(result?.error || "章节创建失败"); setModal(null); setNotice("章节已创建，请继续上传资料。"); await refreshData(); } catch (error) { setNotice(error instanceof Error ? error.message : "章节创建失败，请稍后重试。"); } };
  const joinClass = async (code: string) => { try { const response = await fetch("/api/classroom", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "join", joinCode: code }) }); const result = await response.json().catch(() => null) as { error?: string; class?: { name?: string } } | null; if (!response.ok) throw new Error(result?.error || "加入班级失败"); setModal(null); setNotice(`已加入${result?.class?.name ?? data.class.name}。`); await refreshData(); } catch (error) { setNotice(error instanceof Error ? error.message : "加入班级失败，请稍后重试。"); } };
  const createClass = async () => { (window as Window & { __qktCreateClass?: boolean }).__qktCreateClass = true; setModal("chapter"); };
  const createClassFromForm = async (name: string, courseName: string) => { try { const response = await fetch("/api/classroom", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "create", name, courseName }) }); const result = await response.json().catch(() => null) as { error?: string; class?: { id?: string; name?: string } } | null; if (!response.ok) throw new Error(result?.error || "创建班级失败"); setModal(null); setNotice(`已创建${result?.class?.name ?? name}，当前已切换到新班级。`); await refreshData(result?.class?.id); } catch (error) { setNotice(error instanceof Error ? error.message : "创建班级失败，请稍后重试。"); } };
  const loadDemoData = async () => { try { const response = await fetch("/api/demo", { method: "POST" }); if (!response.ok) throw new Error("demo_load_failed"); await refreshData(); setNotice("完整体验数据已载入：资料、任务、作业、课堂互动和学情分析都可以体验了。"); } catch { setNotice("体验数据载入失败，请稍后重试。"); } };
  const submit = async (content: string) => { const assignment = data.assignments.find((item) => item.id === selectedAssignmentId) ?? data.assignments[0]; const student = data.students[0]; if (!assignment || !student) return; try { const response = await fetch("/api/submissions", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ assignmentId: assignment.id, studentId: student.id, content }) }); if (!response.ok) throw new Error("submit_failed"); await refreshData(); setNotice("作业提交成功，教师可以查看你的最新版本。"); } catch { setNotice("提交失败，请稍后重试。"); } };
  const grade = async (payload: GradePayload) => { try { const response = await fetch("/api/submissions", { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) }); if (!response.ok) throw new Error("grade_failed"); await refreshData(); setNotice("评分和评语已保存。"); } catch { setNotice("评分失败，请稍后重试。"); } };
  return <div className="app-shell"><header className="topbar"><div className="brand-lockup"><div className="brand-mark">教</div><div><p className="brand-name">轻课台</p><p className="brand-subtitle">轻量智能教学系统</p></div></div><div className="topbar-center"><label className="class-switcher-label" htmlFor="class-switcher">当前班级</label><select id="class-switcher" className="class-switcher" value={selectedClassId || data.class.id} onChange={(event) => { setSelectedClassId(event.target.value); refreshData(event.target.value).catch((error) => setNotice(error instanceof Error ? error.message : "班级切换失败，请稍后重试。")); }}><option value={data.class.id}>{data.class.name}</option>{classes.filter((item) => item.id !== data.class.id).map((item) => <option key={item.id} value={item.id}>{item.name} · {item.courseName}</option>)}</select>{role === "teacher" && <button type="button" className="text-button class-create-button" onClick={createClass}>＋ 新建班级</button>}</div><div className="topbar-actions">{!initialRole && <div className="role-toggle" aria-label="切换预览角色"><button type="button" className={role === "teacher" ? "role-active" : ""} onClick={() => switchRole("teacher")}>教师端</button><button type="button" className={role === "student" ? "role-active" : ""} onClick={() => switchRole("student")}>学生端</button></div>}<div className="user-chip"><span className="avatar">{role === "teacher" ? "王" : "张"}</span><span className="user-name">{role === "teacher" ? "王老师" : "张三"}</span><button type="button" className="logout-button" onClick={() => { document.cookie = "demo-role=; path=/; max-age=0"; window.location.replace("/"); }}>退出</button></div></div></header><div className="app-body"><aside className="sidebar"><div className="sidebar-heading">{role === "teacher" ? "教师工作台" : "我的学习"}</div><nav className="sidebar-nav" aria-label="主导航">{nav.map((item) => <button key={item.id} type="button" className={`nav-item ${page === item.id ? "nav-active" : ""}`} onClick={() => setPage(item.id)}><span className="nav-icon" aria-hidden="true">{item.icon}</span><span>{item.label}</span></button>)}</nav><div className="sidebar-footer">{role === "teacher" ? <><button type="button" className="nav-item" onClick={() => setNotice("班级设置已准备就绪，后续可接入真实成员权限。")}><span className="nav-icon">⚙</span><span>班级设置</span></button><button type="button" className="nav-item" onClick={loadDemoData}><span className="nav-icon">✦</span><span>载入体验数据</span></button></> : <button type="button" className="nav-item" onClick={() => setModal("join")}><span className="nav-icon">＋</span><span>加入其他班级</span></button>}<div className="sidebar-note"><span className="note-dot" />数据随时保存</div></div></aside><main className="main-content">{loading && <div className="sync-line"><span className="sync-dot" />正在同步班级数据…</div>}{role === "teacher" ? <TeacherView page={page} data={data} lesson={lesson} insights={insights} knowledge={knowledge} onCreate={() => setModal("assignment")} onChapter={() => setModal("chapter")} onGrade={grade} onLessonRefresh={refreshData} /> : <StudentView page={page} data={data} lesson={lesson} insights={insights} knowledge={knowledge} selectedAssignmentId={selectedAssignmentId} onSelectAssignment={setSelectedAssignmentId} onSubmit={submit} onJoin={() => setModal("join")} onLessonRefresh={refreshData} />}</main></div>{notice && <button type="button" className="toast" onClick={() => setNotice("")} aria-label="关闭提示">{notice}<span>×</span></button>}{modal === "assignment" && <CreateAssignmentModal chapters={data.chapters} onClose={() => setModal(null)} onSubmit={createAssignment} />}{modal === "chapter" && <CreateChapterModal onClose={() => setModal(null)} onSubmit={addChapter} />}</div>;
}

export default function Home() { return <TeachingApp />; }

function LoginScreen({ onLogin }: { onLogin: (role: Role) => void }) { const [role, setRole] = useState<Role>("teacher"); return <div className="login-shell"><div className="login-card"><div className="brand-lockup login-brand"><div className="brand-mark">教</div><div><p className="brand-name">轻课台</p><p className="brand-subtitle">轻量智能教学系统</p></div></div><p className="eyebrow">需要登录</p><h1>登录你的教学空间</h1><p className="login-copy">本站使用工作区账号识别教师和学生身份；未登录时不会自动进入任何班级。</p><div className="login-role-tabs"><button type="button" className={role === "teacher" ? "role-active" : ""} onClick={() => setRole("teacher")}>教师演示</button><button type="button" className={role === "student" ? "role-active" : ""} onClick={() => setRole("student")}>学生演示</button></div><label className="form-label" htmlFor="login-email">账号（演示入口无需填写）</label><input id="login-email" className="form-input" value={role === "teacher" ? "teacher@example.com" : "student@example.com"} readOnly /><label className="form-label" htmlFor="login-password">密码</label><input id="login-password" className="form-input" type="password" value="仅用于本地演示" readOnly /><button type="button" className="primary-button login-button" onClick={() => onLogin(role)}>进入{role === "teacher" ? "教师演示端" : "学生演示端"}</button><p className="login-hint">正式账号由平台登录态提供；演示入口只用于体验，不会冒充真实用户。</p></div></div>; }

function AuthLoadingScreen() { return <div className="login-shell"><div className="login-card"><div className="brand-lockup login-brand"><div className="brand-mark">教</div><div><p className="brand-name">轻课台</p><p className="brand-subtitle">轻量智能教学系统</p></div></div><p className="eyebrow">正在验证</p><h1>正在确认登录身份</h1><p className="login-copy">请稍候，系统会先检查当前平台账号，再决定进入教师端、学生端或登录入口。</p><div className="sync-line"><span className="sync-dot" />正在验证当前账号…</div></div></div>; }

function NoClassScreen({ role, onDemo }: { role: Role; onDemo: (role: Role) => void }) { return <div className="login-shell"><div className="login-card"><div className="brand-lockup login-brand"><div className="brand-mark">教</div><div><p className="brand-name">轻课台</p><p className="brand-subtitle">轻量智能教学系统</p></div></div><p className="eyebrow">正式账号已识别</p><h1>当前账号还没有班级</h1><p className="login-copy">你已通过平台登录，但当前账号尚未加入轻课台班级。请让教师邀请你、使用班级码加入，或切换到演示数据体验完整功能。</p><button type="button" className="primary-button login-button" onClick={() => onDemo(role)}>进入{role === "teacher" ? "教师" : "学生"}演示端</button><p className="login-hint">演示端使用隔离的体验数据，不会写入你的正式账号。</p></div></div>; }

function TeacherView({ page, data, lesson, insights, knowledge, onCreate, onChapter, onGrade, onLessonRefresh }: { page: Page; data: ClassroomData; lesson: LessonData; insights: InsightData; knowledge: KnowledgeData; onCreate: () => void; onChapter: () => void; onGrade: (payload: GradePayload) => void; onLessonRefresh: () => Promise<void> }) { if (page === "content") return <TeacherContent data={data} onChapter={onChapter} onRefresh={onLessonRefresh} />; if (page === "assignments") return <><TeacherAssignments data={data} onCreate={onCreate} /><TeacherPersonalizedPanel data={data} /></>; if (page === "tasks") return <TeacherTasks data={data} />; if (page === "classroom") return <TeacherClassroom data={data} lesson={lesson} onRefresh={onLessonRefresh} />; if (page === "insights") return <TeacherInsights data={insights} />; if (page === "knowledge") return <TeacherKnowledge data={data} lesson={lesson} knowledge={knowledge} onRefresh={onLessonRefresh} />; if (page === "ai") return <TeacherAICopilot data={data} />; if (page === "submissions") return <><TeacherSubmissions data={data} onGrade={onGrade} /><TeacherAuditPanel /></>; return <><TeacherOverview data={data} onCreate={onCreate} onChapter={onChapter} /><TeacherRosterPanel data={data} onRefresh={onLessonRefresh} /></>; }
function TeacherOverview({ data, onCreate, onChapter }: { data: ClassroomData; onCreate: () => void; onChapter: () => void }) { const pending = data.submissions.filter((item) => item.status !== "graded").length; return <div className="page-stack"><div className="page-heading-row"><div><p className="breadcrumb">我的班级 / {data.class.name}</p><h1>班级首页</h1><p className="page-description">今天也从一件小事开始，把课程内容和学生进度整理好。</p></div><button type="button" className="primary-button" onClick={onCreate}>＋ 发布新作业</button></div><section className="class-hero"><div><div className="hero-label">{data.class.term} · 课程班级</div><h2>{data.class.name}</h2><p>{data.class.teacherName} · {data.students.length} 名学生 · 班级码 <strong>{data.class.joinCode}</strong></p></div><button type="button" className="secondary-button" onClick={() => navigator.clipboard?.writeText(data.class.joinCode)}>复制班级码</button></section><div className="metric-grid"><Metric label="章节" value={String(data.chapters.length)} detail={`${data.chapters.filter((item) => item.status === "已发布").length} 个已发布`} /><Metric label="学生" value={String(data.students.length)} detail="本学期成员" /><Metric label="待批改作业" value={String(pending)} detail="需要你的反馈" /><Metric label="资料" value={String(data.materials.length)} detail="已上传文件" /></div><section className="content-section"><SectionTitle title="最近课程内容" description="从章节开始，继续准备你的下一次教学。" action={<button type="button" className="text-button" onClick={onChapter}>＋ 创建章节</button>} /><div className="chapter-list">{data.chapters.map((chapter, index) => <div className="chapter-row" key={chapter.id}><div className="chapter-number">{String(index + 1).padStart(2, "0")}</div><div className="chapter-main"><h3>{chapter.name}</h3><p>{chapter.files} 个教学资料</p></div><Badge tone={chapter.status === "草稿" ? "amber" : "green"}>{chapter.status}</Badge><span className="row-action">进入章节 →</span></div>)}</div></section><section className="split-section"><div className="content-section compact-section"><SectionTitle title="待处理作业" description="最近需要你查看的提交。" /><div className="mini-list">{data.submissions.filter((item) => item.status !== "graded").slice(0, 4).map((submission) => <div className="mini-row" key={submission.id}><span className="mini-avatar">{data.students.find((student) => student.id === submission.student_id)?.initials ?? "学"}</span><div><strong>{data.students.find((student) => student.id === submission.student_id)?.name ?? "学生"}</strong><p>{data.assignments.find((item) => item.id === submission.assignment_id)?.name ?? "作业"}</p></div><Badge tone="amber">待批改</Badge></div>)}{pending === 0 && <div className="empty-record">目前没有待批改提交。</div>}</div></div><div className="content-section compact-section next-step-card"><div className="next-step-mark">↗</div><p className="eyebrow">下一步建议</p><h3>为课程准备一份新作业</h3><p>先创建章节和资料，再发布一份练习，学生即可开始提交。</p><button type="button" className="secondary-button" onClick={onCreate}>开始创建</button></div></section></div>; }

function TeacherRosterPanel({ data, onRefresh }: { data: ClassroomData; onRefresh: () => Promise<void> }) {
  const [csv, setCsv] = useState("姓名,邮箱\n"); const [busy, setBusy] = useState(false); const [message, setMessage] = useState("");
  async function importStudents() { setBusy(true); setMessage(""); try { const response = await fetch("/api/students/import", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ csv }) }); const result = await response.json().catch(() => null) as { error?: string; imported?: number; skipped?: number; errors?: string[] } | null; if (!response.ok) throw new Error(result?.error || "导入失败"); await onRefresh().catch(() => undefined); setMessage(`已导入 ${result?.imported ?? 0} 名学生，跳过 ${result?.skipped ?? 0} 行。${result?.errors?.length ? ` ${result.errors.join("；")}` : ""}`); setCsv("姓名,邮箱\n"); } catch (cause) { setMessage(cause instanceof Error ? cause.message : "导入失败，请重试"); } finally { setBusy(false); } }
  return <section className="content-section roster-panel"><div className="page-heading-row"><div><h2>批量导入学生</h2><p className="page-description">按“姓名,邮箱”逐行粘贴名单，导入前会检查格式和重复成员。</p></div><Badge tone="blue">{data.students.length} 名成员</Badge></div><textarea className="answer-box small-answer roster-input" value={csv} onChange={(event) => setCsv(event.target.value)} aria-label="学生 CSV 名单" placeholder={"姓名,邮箱\n张三,zhangsan@example.com\n李四,lisi@example.com"} /><div className="form-actions"><button type="button" className="secondary-button" onClick={() => setCsv("姓名,邮箱\n张三,zhangsan@example.com\n李四,lisi@example.com")}>填入示例</button><button type="button" className="primary-button" onClick={importStudents} disabled={busy || csv.trim().split(/\r?\n/).length < 2}>{busy ? "导入中…" : "导入名单"}</button></div>{message && <div className={message.includes("失败") ? "inline-error" : "feedback-box"} role="status">{message}</div>}<div className="roster-preview">{data.students.slice(0, 8).map((student) => <span key={student.id}>{student.initials} {student.name}</span>)}</div></section>;
}
function TeacherContent({ data, onChapter, onRefresh }: { data: ClassroomData; onChapter: () => void; onRefresh: () => Promise<void> }) {
  const current = data.chapters[data.chapters.length - 1];
  const materials = data.materials.filter((item) => item.chapterId === current?.id);
  const [uploading, setUploading] = useState(false);
  const [message, setMessage] = useState("");
  const [draft, setDraft] = useState<AIDraft | null>(null);
  const [selectedQuestion, setSelectedQuestion] = useState(0);
  async function uploadMaterial(event: React.ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];
    event.target.value = "";
    if (!file || !current) return;
    setUploading(true); setMessage(""); setDraft(null);
    try {
      const form = new FormData(); form.append("chapterId", current.id); form.append("file", file);
      const response = await fetch("/api/materials", { method: "POST", body: form });
      const result = await response.json().catch(() => null) as { material?: { name?: string; type?: string }; error?: string } | null;
      if (!response.ok) throw new Error(result?.error || "材料上传失败，请重试");
      await onRefresh().catch(() => undefined);
      const text = /\.(txt|md)$/i.test(file.name) ? await file.text().catch(() => "") : "";
      const aiResponse = await fetch("/api/ai/drafts", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ materialName: result?.material?.name ?? file.name, materialType: result?.material?.type ?? file.name.split(".").pop()?.toUpperCase(), text }) });
      const aiResult = await aiResponse.json().catch(() => null) as { draft?: AIDraft; error?: string } | null;
      if (!aiResponse.ok || !aiResult?.draft) throw new Error(aiResult?.error || "AI 识别失败，请稍后重试");
      setDraft(aiResult.draft); setSelectedQuestion(0); setMessage("材料已上传，AI 已生成待审核题目草稿。");
    } catch (error) { setMessage(error instanceof Error ? error.message : "材料处理失败，请重试"); }
    finally { setUploading(false); }
  }
  function useDraft() {
    const question = draft?.questions[selectedQuestion];
    if (!question) return;
    localStorage.setItem("ai-draft-question", JSON.stringify({ prompt: question.prompt, options: question.options, sourceName: draft.sourceName }));
    setMessage("题目草稿已送入课堂互动，请打开左侧“课堂互动”继续审核并发布。");
  }
  return <div className="page-stack"><div className="page-heading-row"><div><p className="breadcrumb">课程内容 / {data.class.name}</p><h1>章节和资料</h1><p className="page-description">先导入材料，再让 AI 提取知识点并生成可编辑题目草稿。</p></div><button type="button" className="primary-button" onClick={onChapter}>＋ 创建章节</button></div><section className="content-section"><SectionTitle title="章节目录" description={`${data.chapters.length} 个章节 · ${data.materials.length} 个资料`} action={<button type="button" className="secondary-button" onClick={onChapter}>创建章节</button>} /><div className="chapter-list">{data.chapters.map((chapter, index) => <div className="chapter-row" key={chapter.id}><div className="chapter-number">{String(index + 1).padStart(2, "0")}</div><div className="chapter-main"><h3>{chapter.name}</h3><p>{chapter.files} 个教学资料 · 最近更新昨天</p></div><Badge tone={chapter.status === "草稿" ? "amber" : "green"}>{chapter.status}</Badge><span className="row-action">管理资料 →</span></div>)}</div></section><section className="content-section material-preview"><SectionTitle title={current?.name ?? "当前章节"} description="上传后自动生成 AI 题目草稿，教师确认后才会发布" /><div className="material-list">{materials.map((material) => <MaterialRow key={material.id} material={material} />)}{materials.length === 0 && <div className="empty-record">还没有资料，上传第一个文件吧。</div>}</div><label className="upload-hint"><span>{uploading ? "…" : "＋"}</span><div><strong>{uploading ? "正在分析材料…" : "导入材料并生成题目"}</strong><p>支持 PDF、PPT、Word、图片、TXT、Markdown；教师审核后才会进入课堂</p></div><input type="file" className="visually-hidden" accept=".pdf,.ppt,.pptx,.doc,.docx,.png,.jpg,.jpeg,.txt,.md" onChange={uploadMaterial} disabled={uploading || !current} /></label></section>{message && <div className={message.includes("失败") ? "inline-error" : "feedback-box"} role="status">{message}</div>}{draft && <section className="content-section ai-draft-card"><SectionTitle title="AI 题目草稿（待审核）" description={draft.summary} /><div className="ai-meta"><span>知识点：{draft.knowledgePoints.join(" · ")}</span><Badge tone="amber">教师确认后发布</Badge></div><label className="form-label" htmlFor="ai-question-select">选择一道题送入课堂</label><select id="ai-question-select" className="form-input" value={selectedQuestion} onChange={(event) => setSelectedQuestion(Number(event.target.value))}>{draft.questions.map((question, index) => <option key={question.id} value={index}>{index + 1}. {question.prompt}</option>)}</select><div className="answer-preview"><strong>{draft.questions[selectedQuestion]?.prompt}</strong><p>{draft.questions[selectedQuestion]?.options.join(" / ")}</p><small>生成依据：{draft.questions[selectedQuestion]?.reason}</small></div><button type="button" className="primary-button" onClick={useDraft}>送入课堂互动</button><div className="inline-note"><span className="info-mark">i</span>当前体验环境使用可追踪的材料识别演示；接入模型后可替换为真实 PDF/PPT/图片内容解析。</div></section>}</div>;
}
function MaterialRow({ material }: { material: Material }) { return <div className="material-row"><span className="file-icon">{material.type}</span><div className="material-name"><strong>{material.name}</strong><p>{material.size} · 昨天更新</p></div><button type="button" className="text-button" onClick={() => material.downloadUrl && window.open(material.downloadUrl, "_blank")}>下载</button><button type="button" className="row-menu" aria-label={`更多操作：${material.name}`}>•••</button></div>; }
function TeacherAssignments({ data, onCreate }: { data: ClassroomData; onCreate: () => void }) { const [filter, setFilter] = useState("全部"); const rows = filter === "全部" ? data.assignments : data.assignments.filter((item) => item.status === filter); return <div className="page-stack"><div className="page-heading-row"><div><p className="breadcrumb">我的班级 / 作业</p><h1>作业管理</h1><p className="page-description">创建作业、设置截止时间，并查看学生完成情况。</p></div><button type="button" className="primary-button" onClick={onCreate}>＋ 发布新作业</button></div><section className="content-section"><div className="table-toolbar"><div className="filter-tabs">{["全部", "进行中", "草稿", "已结束"].map((name) => <button type="button" key={name} className={filter === name ? "filter-active" : ""} onClick={() => setFilter(name)}>{name} <span>{name === "全部" ? data.assignments.length : data.assignments.filter((item) => item.status === name).length}</span></button>)}</div><button type="button" className="secondary-button" onClick={() => setFilter("全部")}>清除筛选</button></div><div className="assignment-table"><div className="table-head"><span>作业名称</span><span>所属章节</span><span>截止时间</span><span>提交情况</span><span>状态</span><span /></div>{rows.map((assignment) => <div className="table-row" key={assignment.id}><div className="table-title"><strong>{assignment.name}</strong><p>普通作业 · 可重复提交</p></div><span>{assignment.chapter}</span><span>{assignment.deadline}</span><span>{assignment.submitted}</span><Badge tone={assignment.status === "进行中" ? "blue" : assignment.status === "草稿" ? "amber" : "gray"}>{assignment.status}</Badge><span className="row-action">查看提交 →</span></div>)}{rows.length === 0 && <div className="empty-record">没有符合条件的作业。</div>}</div></section></div>; }
function TeacherPersonalizedPanel({ data }: { data: ClassroomData }) {
  const [chapterId, setChapterId] = useState(data.chapters.at(-1)?.id ?? ""); const [studentId, setStudentId] = useState(data.students[0]?.id ?? ""); const [count, setCount] = useState("3"); const [drafts, setDrafts] = useState<PersonalizedDraft[]>([]); const [busy, setBusy] = useState(false); const [message, setMessage] = useState("");
  async function load() { const response = await fetch("/api/personalized", { cache: "no-store" }); if (response.ok) { const result = await response.json() as { drafts?: PersonalizedDraft[] }; setDrafts(result.drafts ?? []); } }
  useEffect(() => { load().catch(() => undefined); }, []);
  async function generate() { setBusy(true); setMessage(""); try { const response = await fetch("/api/personalized", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ chapterId, studentId, count: Number(count) }) }); const result = await response.json().catch(() => null) as { error?: string } | null; if (!response.ok) throw new Error(result?.error || "生成失败"); await load(); setMessage("个性化作业草稿已生成，请先审核题目。"); } catch (cause) { setMessage(cause instanceof Error ? cause.message : "生成失败，请重试"); } finally { setBusy(false); } }
  async function review(id: string, status: "published" | "rejected") { setBusy(true); try { const response = await fetch("/api/personalized", { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ draftId: id, status }) }); if (!response.ok) throw new Error("review_failed"); await load(); setMessage(status === "published" ? "已发布给指定学生。" : "草稿已拒绝并保留记录。"); } catch { setMessage("审核失败，请重试"); } finally { setBusy(false); } }
  return <div className="page-stack"><section className="content-section"><div className="page-heading-row"><div><p className="breadcrumb">作业管理 / 个性化作业</p><h2>为学生生成针对性练习</h2><p className="page-description">从题库中优先选择掌握度较低知识点的题目，教师审核后定向发布。</p></div><Badge tone="amber">教师审核后发布</Badge></div><div className="ai-generate-row"><select className="form-input" value={chapterId} onChange={(event) => setChapterId(event.target.value)}><option value="">选择章节</option>{data.chapters.map((chapter) => <option key={chapter.id} value={chapter.id}>{chapter.name}</option>)}</select><select className="form-input" value={studentId} onChange={(event) => setStudentId(event.target.value)}><option value="">选择学生</option>{data.students.map((student) => <option key={student.id} value={student.id}>{student.name}</option>)}</select><select className="form-input" value={count} onChange={(event) => setCount(event.target.value)}><option value="3">3 道题</option><option value="5">5 道题</option><option value="6">6 道题</option></select><button type="button" className="primary-button" onClick={generate} disabled={busy || !chapterId || !studentId}>{busy ? "生成中…" : "生成作业草稿"}</button></div>{message && <div className={message.includes("失败") ? "inline-error" : "feedback-box"} role="status">{message}</div>}</section><section className="content-section"><SectionTitle title="个性化作业草稿" description="题目来自课程题库，来源、难度和知识点会一并保留。" /><div className="ai-draft-list">{drafts.map((draft) => <div className="ai-draft-item" key={draft.id}><div className="task-title-line"><strong>{draft.title}</strong><Badge tone={draft.status === "published" ? "green" : draft.status === "rejected" ? "gray" : "amber"}>{draft.status === "published" ? "已发布" : draft.status === "rejected" ? "已拒绝" : "待审核"}</Badge></div><p>{draft.description}</p><div className="ai-source-row">{draft.chapterName} · 定向学生：{draft.studentName} · {draft.questions.length} 道题</div><div className="personalized-question-list">{draft.questions.map((question, index) => <div className="personalized-question" key={question.id}><strong>{index + 1}. {question.stem}</strong><span>{question.knowledgePoint} · {question.difficulty === "easy" ? "基础" : question.difficulty === "hard" ? "提高" : "中等"} · {question.source}</span></div>)}</div>{draft.status === "draft" && <div className="form-actions"><button type="button" className="secondary-button" onClick={() => review(draft.id, "rejected")} disabled={busy}>拒绝</button><button type="button" className="primary-button" onClick={() => review(draft.id, "published")} disabled={busy}>发布给该学生</button></div>}</div>)}{drafts.length === 0 && <div className="empty-record">还没有个性化作业草稿。</div>}</div></section></div>;
}

function PersonalizedStudentPanel() {
  const [items, setItems] = useState<PersonalizedDraft[]>([]); const [answers, setAnswers] = useState<Record<string, Record<string, string>>>({}); const [busy, setBusy] = useState<string | null>(null); const [message, setMessage] = useState("");
  async function load() { const response = await fetch("/api/personalized", { cache: "no-store" }); if (!response.ok) return; const result = await response.json() as { recommendations?: PersonalizedDraft[] }; setItems(result.recommendations ?? []); }
  useEffect(() => { load().catch(() => undefined); }, []);
  async function submit(item: PersonalizedDraft) { setBusy(item.id); setMessage(""); try { const response = await fetch("/api/personalized", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "submit", draftId: item.id, answers: answers[item.id] ?? {} }) }); const result = await response.json().catch(() => null) as { error?: string } | null; if (!response.ok) throw new Error(result?.error || "提交失败"); await load(); setMessage("针对性练习已提交，老师可以查看你的答案。"); } catch (cause) { setMessage(cause instanceof Error ? cause.message : "提交失败，请重试"); } finally { setBusy(null); } }
  if (!items.length) return null;
  return <section className="content-section personalized-student-panel"><SectionTitle title="老师为你准备的针对性练习" description="根据你的学习记录推荐，完成后仍由老师统一查看。" />{message && <div className={message.includes("失败") ? "inline-error" : "feedback-box"} role="status">{message}</div>}{items.map((item) => <div className="personalized-student-card" key={item.id}><div className="task-title-line"><strong>{item.title}</strong><Badge tone="green">已发布</Badge></div><p>{item.description}</p><div className="personalized-question-list">{item.questions.map((question, index) => <div className="personalized-question" key={question.id}><strong>{index + 1}. {question.stem}</strong><span>{question.knowledgePoint} · {question.difficulty === "easy" ? "基础" : question.difficulty === "hard" ? "提高" : "中等"}</span><div className="choice-list compact-choice-list">{question.options.map((option) => <label className={`choice-item ${(answers[item.id]?.[question.id] ?? item.response?.answers?.[question.id]) === option ? "choice-selected" : ""}`} key={option}><input type="radio" name={`${item.id}-${question.id}`} value={option} checked={(answers[item.id]?.[question.id] ?? item.response?.answers?.[question.id] ?? "") === option} onChange={() => setAnswers((current) => ({ ...current, [item.id]: { ...current[item.id], [question.id]: option } }))} /><span>{option}</span></label>)}</div></div>)}</div><div className="form-actions"><button type="button" className="primary-button" onClick={() => submit(item)} disabled={busy === item.id}>{busy === item.id ? "提交中…" : item.response ? "再次提交" : "提交针对性练习"}</button>{item.response && <small className="upload-example">已提交于 {item.response.submittedAt ? new Date(item.response.submittedAt).toLocaleString("zh-CN") : "最近"}</small>}</div></div>)}</section>;
}

function TeacherAuditPanel() {
  const [logs, setLogs] = useState<AuditLog[]>([]); const [expanded, setExpanded] = useState(false); const [loading, setLoading] = useState(false);
  async function load() { setLoading(true); try { const response = await fetch("/api/audit", { cache: "no-store" }); if (response.ok) { const result = await response.json() as { logs?: AuditLog[] }; setLogs(result.logs ?? []); } } finally { setLoading(false); } }
  useEffect(() => { if (expanded) load().catch(() => undefined); }, [expanded]);
  return <section className="content-section"><div className="section-title-row"><div><h2>操作审计</h2><p>记录生成、发布、提交和评分等关键操作，便于追溯问题。</p></div><div className="form-actions"><button type="button" className="secondary-button" onClick={() => window.open("/api/export?type=audit", "_blank")}>导出审计记录</button><button type="button" className="secondary-button" onClick={() => setExpanded((value) => !value)}>{expanded ? "收起" : "查看记录"}</button></div></div>{expanded && <div className="audit-list">{loading ? <div className="empty-record">正在加载操作记录…</div> : logs.map((log) => <div className="audit-row" key={log.id}><div><strong>{log.userName} · {log.action}{log.objectType}</strong><p>{log.detail || log.objectId || "—"}</p></div><time>{new Date(log.createdAt).toLocaleString("zh-CN", { month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit" })}</time></div>)}{!loading && logs.length === 0 && <div className="empty-record">暂无操作记录。</div>}</div>}</section>;
}

function TeacherTasks({ data }: { data: ClassroomData }) { const [tasks, setTasks] = useState(data.tasks); const [type, setType] = useState<LearningTask["type"]>("preview"); const [title, setTitle] = useState(""); const [description, setDescription] = useState(""); const [dueAt, setDueAt] = useState(""); const [saving, setSaving] = useState(false); useEffect(() => setTasks(data.tasks), [data.tasks]); async function publish(event: React.FormEvent) { event.preventDefault(); if (!title.trim()) return; setSaving(true); try { const response = await fetch("/api/tasks", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ type, title, description, dueAt, chapterId: data.chapters.at(-1)?.id }) }); if (!response.ok) throw new Error("task_create_failed"); const result = await response.json() as { task?: LearningTask }; if (result.task) setTasks((current) => [{ ...result.task!, chapterId: data.chapters.at(-1)?.id ?? null, typeLabel: result.task!.typeLabel ?? "学习任务", description, dueAt: dueAt || null, startAt: null, completed: false, completedCount: 0, totalStudents: data.students.length, record: null }, ...current]); setTitle(""); setDescription(""); setDueAt(""); } finally { setSaving(false); } } return <div className="page-stack"><div className="page-heading-row"><div><p className="breadcrumb">我的班级 / 学习任务</p><h1>课前与课后任务</h1><p className="page-description">围绕章节发布预习、资料、作业和复习任务，学生按阶段完成。</p></div></div><div className="task-layout"><section className="content-section"><SectionTitle title="发布学习任务" description="先选择任务阶段，再填写说明和截止时间。" /><form onSubmit={publish}><label className="form-label" htmlFor="task-type">任务类型</label><select id="task-type" className="form-input" value={type} onChange={(event) => setType(event.target.value as LearningTask["type"])}><option value="preview">课前预习</option><option value="material">学习资料</option><option value="assignment">课后作业</option><option value="review">课后复习</option></select><label className="form-label" htmlFor="task-title">任务标题</label><input id="task-title" className="form-input" value={title} onChange={(event) => setTitle(event.target.value)} placeholder="例如：预习循环结构" required /><label className="form-label" htmlFor="task-description">任务说明</label><textarea id="task-description" className="answer-box small-answer" value={description} onChange={(event) => setDescription(event.target.value)} placeholder="告诉学生需要完成什么……" /><label className="form-label" htmlFor="task-due">截止时间（可选）</label><input id="task-due" type="datetime-local" className="form-input" value={dueAt} onChange={(event) => setDueAt(event.target.value)} /><div className="form-actions"><button type="submit" className="primary-button" disabled={saving}>{saving ? "保存中…" : "发布任务"}</button></div></form></section><section className="content-section"><SectionTitle title="已发布任务" description={`${tasks.length} 个任务 · 按截止时间排序`} /><div className="task-list">{tasks.map((task) => <div className="task-row" key={task.id}><div className={`task-icon task-${task.type}`}>{task.type === "preview" ? "预" : task.type === "review" ? "复" : task.type === "assignment" ? "作" : "资"}</div><div className="task-main"><div className="task-title-line"><strong>{task.title}</strong><Badge tone={task.type === "preview" ? "blue" : task.type === "review" ? "green" : "amber"}>{task.typeLabel}</Badge></div><p>{task.description || "未填写说明"}</p><small>完成 {task.completedCount}/{task.totalStudents} 人 · 截止 {task.dueAt ?? "未设置"}</small></div></div>)}{tasks.length === 0 && <div className="empty-record">还没有学习任务。</div>}</div></section></div></div>; }
function TeacherSubmissions({ data, onGrade }: { data: ClassroomData; onGrade: (payload: GradePayload) => void }) { const assignment = data.assignments.find((item) => item.name.includes("循环")) ?? data.assignments[0]; const [selected, setSelected] = useState<Submission | null>(null); const rows = data.students.map((student) => ({ student, submission: data.submissions.find((item) => item.assignment_id === assignment?.id && item.student_id === student.id) })); const submitted = rows.filter((row) => row.submission).length; return <div className="page-stack"><div className="page-heading-row"><div><p className="breadcrumb">学生提交 / {assignment?.name ?? "作业"}</p><h1>学生提交</h1><p className="page-description">已提交 {submitted} 人 · 未提交 {Math.max(data.students.length - submitted, 0)} 人 · 点击学生查看内容并评分。</p></div><button type="button" className="secondary-button" onClick={() => window.open("/api/export?type=submissions", "_blank")}>导出列表</button></div><section className="content-section"><div className="submission-summary"><div><span className="summary-dot blue-dot" />已提交 <strong>{submitted}</strong></div><div><span className="summary-dot amber-dot" />待批改 <strong>{rows.filter((row) => row.submission?.status !== "graded" && row.submission).length}</strong></div><div><span className="summary-dot gray-dot" />未提交 <strong>{Math.max(data.students.length - submitted, 0)}</strong></div></div><div className="submission-table"><div className="table-head"><span>学生</span><span>提交时间</span><span>状态</span><span>分数</span><span /></div>{rows.map(({ student, submission }) => <div className="table-row" key={student.id}><div className="student-cell"><span className="mini-avatar">{student.initials}</span><strong>{student.name}</strong></div><span>{submission?.submitted_at ? new Date(submission.submitted_at).toLocaleString("zh-CN", { month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit" }) : "-"}</span><Badge tone={submission?.status === "graded" ? "green" : submission ? "amber" : "gray"}>{submission?.status === "graded" ? "已批改" : submission ? "待批改" : "未提交"}</Badge><span className="score-text">{submission?.score ?? "-"}</span><button type="button" className="row-action" disabled={!submission} onClick={() => submission && setSelected(submission)}>查看 →</button></div>)}</div></section>{selected && <GradeSubmissionModal submission={selected} studentName={data.students.find((student) => student.id === selected.student_id)?.name ?? "学生"} onClose={() => setSelected(null)} onSubmit={(payload) => { onGrade(payload); setSelected(null); }} />}</div>; }
function StudentView({ page, data, lesson, insights, knowledge, selectedAssignmentId, onSelectAssignment, onSubmit, onJoin, onLessonRefresh }: { page: Page; data: ClassroomData; lesson: LessonData; insights: InsightData; knowledge: KnowledgeData; selectedAssignmentId: string; onSelectAssignment: (id: string) => void; onSubmit: (content: string) => void; onJoin: () => void; onLessonRefresh: () => Promise<void> }) { if (page === "content") return <StudentContent data={data} />; if (page === "assignments") return <><PersonalizedStudentPanel /><StudentAssignments key={selectedAssignmentId} data={data} selectedAssignmentId={selectedAssignmentId} onSelectAssignment={onSelectAssignment} onSubmit={onSubmit} /></>; if (page === "tasks") return <StudentTasks data={data} />; if (page === "classroom") return <StudentClassroom lesson={lesson} onRefresh={onLessonRefresh} />; if (page === "knowledge") return <StudentKnowledge knowledge={knowledge} />; if (page === "record") return <StudentRecord data={data} insights={insights} />; return <StudentOverview data={data} onJoin={onJoin} onSubmit={onSubmit} />; }
function StudentTasks({ data }: { data: ClassroomData }) { const [tasks, setTasks] = useState(data.tasks); const [busy, setBusy] = useState<string | null>(null); useEffect(() => setTasks(data.tasks), [data.tasks]); async function complete(task: LearningTask) { setBusy(task.id); try { const response = await fetch("/api/tasks", { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ taskId: task.id, studentId: data.students[0]?.id, content: "已完成任务" }) }); if (!response.ok) throw new Error("task_complete_failed"); setTasks((current) => current.map((item) => item.id === task.id ? { ...item, completed: true, record: { task_id: item.id, status: "completed", content: "已完成任务", completed_at: new Date().toISOString() } } : item)); } finally { setBusy(null); } } return <div className="page-stack"><div className="page-heading-row"><div><p className="breadcrumb">我的学习 / 学习任务</p><h1>我的学习任务</h1><p className="page-description">按课前、课上、课后查看安排，完成后会同步到教师端。</p></div></div><div className="task-stage-grid"><section className="content-section"><SectionTitle title="课前" description="上课前先完成预习。" />{tasks.filter((task) => task.type === "preview").map((task) => <TaskStudentRow key={task.id} task={task} busy={busy === task.id} onComplete={() => complete(task)} />)}{!tasks.some((task) => task.type === "preview") && <div className="empty-record">暂无预习任务。</div>}</section><section className="content-section"><SectionTitle title="课后" description="完成作业并及时复习。" />{tasks.filter((task) => task.type === "assignment" || task.type === "review" || task.type === "material").map((task) => <TaskStudentRow key={task.id} task={task} busy={busy === task.id} onComplete={() => complete(task)} />)}{!tasks.some((task) => task.type !== "preview") && <div className="empty-record">暂无课后任务。</div>}</section></div></div>; }
function TaskStudentRow({ task, busy, onComplete }: { task: LearningTask; busy: boolean; onComplete: () => void }) { return <div className="task-row"><div className={`task-icon task-${task.type}`}>{task.type === "preview" ? "预" : task.type === "review" ? "复" : task.type === "assignment" ? "作" : "资"}</div><div className="task-main"><div className="task-title-line"><strong>{task.title}</strong><Badge tone={task.completed ? "green" : "amber"}>{task.completed ? "已完成" : task.typeLabel}</Badge></div><p>{task.description || "未填写说明"}</p><small>截止 {task.dueAt ?? "未设置"}</small></div><button type="button" className={task.completed ? "secondary-button" : "primary-button"} disabled={task.completed || busy} onClick={onComplete}>{busy ? "保存中…" : task.completed ? "已完成" : "标记完成"}</button></div>; }
function StudentOverview({ data, onJoin, onSubmit }: { data: ClassroomData; onJoin: () => void; onSubmit: (content: string) => void }) { const todo = data.assignments.find((item) => item.status === "进行中" || item.status === "草稿") ?? data.assignments[0]; return <div className="page-stack"><div className="page-heading-row"><div><p className="breadcrumb">我的班级 / {data.class.name}</p><h1>你好，张三</h1><p className="page-description">继续完成你的学习任务，保持每周的小进步。</p></div><button type="button" className="primary-button" onClick={() => todo && onSubmit("我已经完成了三个循环练习。")}>去完成作业</button></div><section className="class-hero student-hero"><div><div className="hero-label">当前课程</div><h2>{data.class.name}</h2><p>{data.class.teacherName} · {data.class.term} · {data.students.length} 名学生</p></div><span className="student-progress">本周完成 <strong>2/3</strong></span></section><div className="student-grid"><section className="content-section"><SectionTitle title="最近学习内容" description="从上次学习的地方继续。" /><div className="learning-card"><div className="learning-icon">03</div><div><span className="eyebrow">正在学习</span><h3>第 3 章 循环结构</h3><p>3 个资料 · 1 个待完成作业</p></div><button type="button" className="secondary-button">查看章节</button></div></section><section className="content-section"><SectionTitle title="我的作业" description="按时完成作业，及时查看反馈。" /><div className="mini-list">{data.assignments.slice(0, 3).map((assignment) => <div className="mini-row" key={assignment.id}><span className="file-icon">作</span><div><strong>{assignment.name}</strong><p>截止 {assignment.deadline}</p></div><Badge tone={assignment.status === "已结束" ? "green" : "amber"}>{assignment.status === "已结束" ? "已评分" : "待完成"}</Badge></div>)}</div></section></div><div className="join-banner"><div><strong>加入新的班级</strong><p>如果老师给了你新的班级码，可以随时加入。</p></div><button type="button" className="secondary-button" onClick={onJoin}>输入班级码</button></div></div>; }
function StudentContent({ data }: { data: ClassroomData }) { return <div className="page-stack"><div className="page-heading-row"><div><p className="breadcrumb">课程内容 / {data.class.name}</p><h1>课程内容</h1><p className="page-description">按章节查看老师发布的学习资料。</p></div></div><section className="content-section"><SectionTitle title="章节目录" description={`${data.chapters.length} 个章节 · ${data.materials.length} 个资料`} /><div className="chapter-list">{data.chapters.map((chapter, index) => <div className="chapter-row" key={chapter.id}><div className="chapter-number">{String(index + 1).padStart(2, "0")}</div><div className="chapter-main"><h3>{chapter.name}</h3><p>{chapter.files} 个教学资料</p></div><Badge tone={index === data.chapters.length - 1 ? "blue" : "green"}>{index === data.chapters.length - 1 ? "学习中" : "已完成"}</Badge><span className="row-action">查看章节 →</span></div>)}</div></section></div>; }
function StudentAssignments({ data, selectedAssignmentId, onSelectAssignment, onSubmit }: { data: ClassroomData; selectedAssignmentId: string; onSelectAssignment: (id: string) => void; onSubmit: (content: string) => void }) { const assignment = data.assignments.find((item) => item.id === selectedAssignmentId) ?? data.assignments[0]; const existing = data.submissions.find((item) => item.assignment_id === assignment?.id && item.student_id === data.students[0]?.id); const [answer, setAnswer] = useState(existing?.content ?? ""); return <div className="page-stack"><div className="page-heading-row"><div><p className="breadcrumb">我的作业 / {assignment?.chapter ?? "课程"}</p><h1>作业详情</h1><p className="page-description">选择作业后填写回答，提交后仍可再次修改。</p></div><Badge tone={existing?.status === "graded" ? "green" : existing ? "blue" : "amber"}>{existing?.status === "graded" ? `已评分 ${existing.score ?? ""}` : existing ? "已提交" : "待完成"}</Badge></div><div className="assignment-picker">{data.assignments.map((item) => <button type="button" key={item.id} className={item.id === assignment?.id ? "picker-active" : ""} onClick={() => onSelectAssignment(item.id)}>{item.name}<span>{item.deadline}</span></button>)}</div><section className="assignment-detail"><div className="detail-heading"><div><span className="eyebrow">{assignment?.chapter ?? "当前章节"}</span><h2>{assignment?.name ?? "作业"}</h2></div><span className="deadline-label">截止 {assignment?.deadline ?? "未设置"}</span></div><div className="detail-description"><p>{assignment?.description ?? "请完成本章节练习。"}</p></div><label className="form-label" htmlFor="answer">我的回答</label><textarea id="answer" className="answer-box" placeholder="输入文字回答，或粘贴你的代码……" value={answer} onChange={(event) => setAnswer(event.target.value)} /><div className="upload-row"><label className="upload-box"><span className="upload-plus">＋</span><div><strong>添加附件</strong><p>支持代码、图片和文档</p></div><input type="file" className="visually-hidden" /></label><span className="upload-example">提交后以最后一次版本为准</span></div><div className="form-actions"><button type="button" className="secondary-button" onClick={() => alert("草稿已保存在当前设备。")}>保存草稿</button><button type="button" className="primary-button" disabled={!answer.trim()} onClick={() => onSubmit(answer.trim())}>提交作业</button></div>{existing?.feedback && <div className="feedback-box"><strong>教师反馈</strong><p>{existing.feedback}</p></div>}</section></div>; }
function StudentRecord({ data, insights }: { data: ClassroomData; insights: InsightData }) { const records = data.submissions.filter((item) => item.student_id === data.students[0]?.id); const current = insights.students[0]; return <div className="page-stack"><div className="page-heading-row"><div><p className="breadcrumb">我的学习 / {data.class.name}</p><h1>学习记录</h1><p className="page-description">查看作业提交、成绩和教师反馈，了解自己的学习节奏。</p></div></div>{current && <div className="metric-grid"><Metric label="任务完成" value={`${current.completionRate}%`} detail="学习任务完成率" /><Metric label="作业提交" value={`${current.assignmentRate}%`} detail="已提交作业比例" /><Metric label="课堂参与" value={`${current.activityRate}%`} detail="课堂活动参与率" /><Metric label="平均分" value={current.averageScore === null ? "—" : `${current.averageScore}`} detail={current.attention ? current.attentionReason : "表现稳定"} /></div>}<section className="content-section"><SectionTitle title="作业记录" description="最近的提交、成绩与反馈" /><div className="record-list">{records.length === 0 ? <div className="empty-record">还没有作业提交记录，完成一次作业后会显示在这里。</div> : records.map((record) => { const assignment = data.assignments.find((item) => item.id === record.assignment_id); return <div className="record-row" key={record.id}><div className="record-date">{new Date(record.submitted_at).toLocaleDateString("zh-CN", { month: "2-digit", day: "2-digit" })}</div><div className="record-main"><strong>{assignment?.name ?? "作业"}</strong><p>{assignment?.chapter ?? "课程"} · {record.feedback ?? "等待教师反馈"}</p></div>{record.score ? <span className="record-score">{record.score} 分</span> : <Badge tone="amber">待批改</Badge>}</div>; })}</div></section></div>; }

function TeacherKnowledge({ data, lesson, knowledge, onRefresh }: { data: ClassroomData; lesson: LessonData; knowledge: KnowledgeData; onRefresh: () => Promise<void> }) {
  const [name, setName] = useState(""); const [description, setDescription] = useState(""); const [chapterId, setChapterId] = useState(data.chapters.at(-1)?.id ?? "");
  const [pointId, setPointId] = useState(knowledge.points[0]?.id ?? ""); const [objectType, setObjectType] = useState("assignment"); const [objectId, setObjectId] = useState(data.assignments[0]?.id ?? ""); const [message, setMessage] = useState(""); const [saving, setSaving] = useState(false);
  useEffect(() => { if (!pointId && knowledge.points[0]) setPointId(knowledge.points[0].id); if (!data.assignments.some((item) => item.id === objectId) && data.assignments[0]) setObjectId(data.assignments[0].id); }, [knowledge.points, data.assignments, objectId, pointId]);
  async function create(event: React.FormEvent) { event.preventDefault(); if (!name.trim()) return; setSaving(true); setMessage(""); try { const response = await fetch("/api/knowledge", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "create", name, description, chapterId }) }); const result = await response.json().catch(() => null) as { error?: string } | null; if (!response.ok) throw new Error(result?.error || "保存失败"); setName(""); setDescription(""); await onRefresh(); setMessage("知识点已保存。"); } catch (cause) { setMessage(cause instanceof Error ? cause.message : "保存失败，请重试"); } finally { setSaving(false); } }
  async function link(event: React.FormEvent) { event.preventDefault(); if (!pointId || !objectId) return; setSaving(true); setMessage(""); try { const response = await fetch("/api/knowledge", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "link", knowledgePointId: pointId, objectType, objectId }) }); const result = await response.json().catch(() => null) as { error?: string } | null; if (!response.ok) throw new Error(result?.error || "关联失败"); await onRefresh(); setMessage("内容已关联到知识点。"); } catch (cause) { setMessage(cause instanceof Error ? cause.message : "关联失败，请重试"); } finally { setSaving(false); } }
  const options = objectType === "material" ? data.materials.map((item) => ({ id: item.id, label: item.name })) : objectType === "chapter" ? data.chapters.map((item) => ({ id: item.id, label: item.name })) : objectType === "learning_task" ? data.tasks.map((item) => ({ id: item.id, label: item.title })) : objectType === "activity" ? lesson.activities.map((item) => ({ id: item.id, label: item.prompt })) : data.assignments.map((item) => ({ id: item.id, label: item.name }));
  return <div className="page-stack"><div className="page-heading-row"><div><p className="breadcrumb">课程设计 / {knowledge.course.name}</p><h1>知识点与掌握度</h1><p className="page-description">先建立可解释的知识点，再把资料和任务关联进来。</p></div><Badge tone="green">规则计算</Badge></div><div className="task-layout"><section className="content-section"><SectionTitle title="新建知识点" description="知识点属于课程，可归属到一个章节。" /><form onSubmit={create}><label className="form-label" htmlFor="knowledge-name">知识点名称</label><input id="knowledge-name" className="form-input" value={name} onChange={(event) => setName(event.target.value)} placeholder="例如：矩阵的秩" required /><label className="form-label" htmlFor="knowledge-chapter">所属章节</label><select id="knowledge-chapter" className="form-input" value={chapterId} onChange={(event) => setChapterId(event.target.value)}>{data.chapters.map((chapter) => <option key={chapter.id} value={chapter.id}>{chapter.name}</option>)}</select><label className="form-label" htmlFor="knowledge-description">说明</label><textarea id="knowledge-description" className="answer-box small-answer" value={description} onChange={(event) => setDescription(event.target.value)} placeholder="用一句话说明学生需要理解什么。" /><div className="form-actions"><button type="submit" className="primary-button" disabled={saving}>{saving ? "保存中…" : "保存知识点"}</button></div></form><div className="divider" /><SectionTitle title="关联教学内容" description="可关联章节、资料、作业、学习任务或课堂活动。" /><form onSubmit={link}><label className="form-label" htmlFor="knowledge-point">知识点</label><select id="knowledge-point" className="form-input" value={pointId} onChange={(event) => setPointId(event.target.value)}>{knowledge.points.map((point) => <option key={point.id} value={point.id}>{point.name}</option>)}</select><label className="form-label" htmlFor="knowledge-object-type">内容类型</label><select id="knowledge-object-type" className="form-input" value={objectType} onChange={(event) => { const next = event.target.value; setObjectType(next); const nextOptions = next === "material" ? data.materials : next === "chapter" ? data.chapters : next === "learning_task" ? data.tasks : next === "activity" ? lesson.activities : data.assignments; setObjectId(nextOptions[0]?.id ?? ""); }}>{<><option value="assignment">作业</option><option value="material">资料</option><option value="chapter">章节</option><option value="learning_task">学习任务</option><option value="activity">课堂活动</option></>}</select><label className="form-label" htmlFor="knowledge-object">选择内容</label><select id="knowledge-object" className="form-input" value={objectId} onChange={(event) => setObjectId(event.target.value)}>{options.map((option) => <option key={option.id} value={option.id}>{option.label}</option>)}</select><div className="form-actions"><button type="submit" className="secondary-button" disabled={saving || !pointId || !objectId}>建立关联</button></div></form>{message && <div className={message.includes("失败") ? "inline-error" : "feedback-box"} role="status">{message}</div>}</section><section className="content-section"><SectionTitle title="知识点列表" description={`${knowledge.points.length} 个知识点 · 掌握度来自已保存的学习证据`} /><div className="task-list">{knowledge.points.map((point) => <div className="task-row" key={point.id}><div className="task-icon task-preview">知</div><div className="task-main"><div className="task-title-line"><strong>{point.name}</strong><Badge tone="blue">{point.chapterName}</Badge></div><p>{point.description || "暂未填写说明"}</p><small>{point.links.length ? `已关联 ${point.links.length} 项内容` : "尚未关联教学内容"}</small><div className="knowledge-mastery-grid">{point.mastery.map((item) => <div className="knowledge-student-chip" key={item.studentId}><span>{item.studentName}</span><b>{item.score === null ? "暂无数据" : `${item.score} 分`}</b><small>{item.evidenceCount} 条依据</small></div>)}</div></div></div>)}{knowledge.points.length === 0 && <div className="empty-record">还没有知识点，先从左侧创建一个。</div>}</div></section></div></div>;
}

function StudentKnowledge({ knowledge }: { knowledge: KnowledgeData }) { return <div className="page-stack"><div className="page-heading-row"><div><p className="breadcrumb">我的学习 / 知识点掌握</p><h1>知识点掌握</h1><p className="page-description">根据已评分作业和学习记录，查看自己的掌握证据。</p></div><Badge tone="green">只显示本人</Badge></div><section className="content-section"><SectionTitle title={knowledge.course.name} description="掌握度不足时，先查看依据并回到对应章节复习。" /><div className="knowledge-student-list">{knowledge.points.map((point) => { const item = point.mastery[0]; return <div className="knowledge-student-card" key={point.id}><div className="task-title-line"><div><strong>{point.name}</strong><p>{point.chapterName} · {point.description || "暂无说明"}</p></div><Badge tone={item?.score !== null && item?.score !== undefined ? (item.score >= 80 ? "green" : "amber") : "gray"}>{item?.score === null || !item ? "暂无数据" : `${item.score} 分`}</Badge></div><div className="knowledge-evidence-list">{item?.evidence?.length ? item.evidence.map((evidence, index) => <div className="knowledge-evidence" key={`${evidence.type}-${index}`}><span className="event-dot" /><div><strong>{evidence.label}</strong><p>{evidence.detail}</p></div></div>) : <div className="empty-record">还没有足够的学习证据，完成相关作业或任务后会更新。</div>}</div></div>; })}{knowledge.points.length === 0 && <div className="empty-record">老师还没有建立知识点。</div>}</div></section></div>; }

function TeacherAICopilot({ data }: { data: ClassroomData }) {
  const [drafts, setDrafts] = useState<AIDraftRecord[]>([]); const [chapterId, setChapterId] = useState(data.chapters.at(-1)?.id ?? ""); const [busy, setBusy] = useState(false); const [message, setMessage] = useState("");
  async function load() { const response = await fetch("/api/ai/drafts", { cache: "no-store" }); if (response.ok) { const result = await response.json() as { drafts?: AIDraftRecord[] }; setDrafts(result.drafts ?? []); } }
  useEffect(() => { load().catch(() => undefined); }, []);
  async function generate() { setBusy(true); setMessage(""); try { const response = await fetch("/api/ai/drafts", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ draftType: "insight", chapterId }) }); const result = await response.json().catch(() => null) as { error?: string } | null; if (!response.ok) throw new Error(result?.error || "生成失败"); await load(); setMessage("AI 学情摘要已生成，等待教师审核。"); } catch (cause) { setMessage(cause instanceof Error ? cause.message : "生成失败，请重试"); } finally { setBusy(false); } }
  async function review(draftId: string, status: "confirmed" | "rejected") { setBusy(true); try { const response = await fetch("/api/ai/drafts", { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ draftId, status }) }); if (!response.ok) throw new Error("review_failed"); await load(); setMessage(status === "confirmed" ? "草稿已确认保存，尚未自动发布。" : "草稿已拒绝并保留记录。"); } catch { setMessage("审核失败，请重试"); } finally { setBusy(false); } }
  return <div className="page-stack"><div className="page-heading-row"><div><p className="breadcrumb">教师工作台 / AI 助教</p><h1>AI 教学副驾驶</h1><p className="page-description">基于章节、知识点和学习数据生成可审核的教学草稿。</p></div><Badge tone="amber">教师确认后生效</Badge></div><section className="content-section"><SectionTitle title="生成学情摘要" description="摘要只读取当前课程数据，不会自动修改成绩或发布内容。" /><div className="ai-generate-row"><select className="form-input" value={chapterId} onChange={(event) => setChapterId(event.target.value)}>{data.chapters.map((chapter) => <option key={chapter.id} value={chapter.id}>{chapter.name}</option>)}</select><button type="button" className="primary-button" onClick={generate} disabled={busy || !chapterId}>{busy ? "生成中…" : "生成 AI 学情摘要"}</button></div>{message && <div className={message.includes("失败") ? "inline-error" : "feedback-box"} role="status">{message}</div>}</section><section className="content-section"><SectionTitle title="草稿箱" description="可确认、拒绝或稍后继续修改；所有草稿都保留来源。" /><div className="ai-draft-list">{drafts.map((draft) => { const payload = draft.payload as AIDraftPayload; return <div className="ai-draft-item" key={draft.id}><div className="task-title-line"><strong>{draft.title}</strong><Badge tone={draft.status === "confirmed" ? "green" : draft.status === "rejected" ? "gray" : "amber"}>{draft.status === "confirmed" ? "已确认" : draft.status === "rejected" ? "已拒绝" : "待审核"}</Badge></div><p>{draft.summary}</p><div className="ai-source-row">来源：{draft.sourceRefs.map((source) => source.label).join(" · ") || "当前课程数据"}</div>{draft.type === "insight" && payload.suggestions?.length ? <div className="ai-suggestion-list">{payload.suggestions.map((item) => <span key={item}>{item}</span>)}</div> : null}{draft.type === "activity" && payload.questions?.length ? <div className="ai-source-row">包含 {payload.questions.length} 道待审核课堂题目 · 材料：{payload.sourceName ?? "未命名"}</div> : null}{draft.status === "draft" && <div className="form-actions"><button type="button" className="secondary-button" onClick={() => review(draft.id, "rejected")} disabled={busy}>拒绝</button><button type="button" className="primary-button" onClick={() => review(draft.id, "confirmed")} disabled={busy}>确认保存</button></div>}</div>; })}{drafts.length === 0 && <div className="empty-record">还没有 AI 草稿，先生成一份学情摘要。</div>}</div></section></div>;
}

function TeacherInsights({ data }: { data: InsightData }) { const attention = data.students.filter((student) => student.attention); const distribution = Object.entries(data.class.scoreDistribution); return <div className="page-stack"><div className="page-heading-row"><div><p className="breadcrumb">我的班级 / 学情分析</p><h1>基础学情</h1><p className="page-description">用可追溯的学习事件，查看班级完成率、参与率与待关注学生。</p></div><Badge tone="green">数据已更新</Badge></div><div className="metric-grid"><Metric label="预习完成率" value={`${data.class.previewCompletionRate}%`} detail="学习任务中的预习" /><Metric label="作业完成率" value={`${data.class.assignmentCompletionRate}%`} detail="已有提交记录" /><Metric label="活动参与率" value={`${data.class.activityParticipationRate}%`} detail="课堂活动参与情况" /><Metric label="平均分" value={data.class.averageScore === null ? "—" : `${data.class.averageScore}`} detail="已评分作业" /></div><div className="insight-layout"><section className="content-section"><SectionTitle title="学生状态" description="低于 50% 的指标会进入待关注列表。" /><div className="insight-student-list">{data.students.map((student) => <div className="insight-student-row" key={student.id}><span className="mini-avatar">{student.initials}</span><div className="insight-student-main"><div className="task-title-line"><strong>{student.name}</strong><Badge tone={student.attention ? "amber" : "green"}>{student.attention ? "待关注" : "稳定"}</Badge></div><p>任务 {student.completionRate}% · 作业 {student.assignmentRate}% · 活动 {student.activityRate}%{student.averageScore === null ? "" : ` · 平均 ${student.averageScore} 分`}</p><small>{student.attentionReason}</small></div></div>)}{data.students.length === 0 && <div className="empty-record">暂无学生学习数据。</div>}</div></section><section className="content-section"><SectionTitle title="分数分布" description={`${attention.length} 位学生需要关注`} /><div className="score-distribution">{distribution.length === 0 ? <div className="empty-record">暂无评分数据。</div> : distribution.map(([label, count]) => <div className="distribution-row" key={label}><span>{label}</span><div className="distribution-bar"><i style={{ width: `${data.class.averageScore ? Math.min(100, count * 20) : 0}%` }} /></div><b>{count}</b></div>)}</div><SectionTitle title="最近事件" description="每条数据都可以追溯到具体操作。" />{data.events.slice(0, 6).map((event) => <div className="event-row" key={event.id}><span className="event-dot" /><div><strong>{event.studentName} · {event.label}</strong><p>{new Date(event.occurredAt).toLocaleString("zh-CN", { month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit" })}</p></div></div>)}{data.events.length === 0 && <div className="empty-record">还没有新的学习事件。</div>}</section></div></div>; }

function Modal({ children, onClose }: { children: React.ReactNode; onClose: () => void }) { return <div className="modal-backdrop" role="presentation" onMouseDown={onClose}><form className="modal-card" role="dialog" aria-modal="true" onMouseDown={(event) => event.stopPropagation()}>{children}</form></div>; }
function CreateAssignmentModal({ chapters, onClose, onSubmit }: { chapters: Chapter[]; onClose: () => void; onSubmit: (payload: { name: string; chapterId: string; description: string; deadline: string }) => void }) { function submit(event: React.FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); onSubmit({ name: String(form.get("name") ?? "").trim(), chapterId: String(form.get("chapterId") ?? chapters[0]?.id ?? ""), description: String(form.get("description") ?? "").trim(), deadline: String(form.get("deadline") ?? "").trim() }); } return <Modal onClose={onClose}><div className="modal-header"><div><p className="eyebrow">新建任务</p><h2>发布作业</h2></div><button type="button" className="close-button" onClick={onClose}>×</button></div><label className="form-label" htmlFor="assignment-name">作业名称</label><input id="assignment-name" name="name" className="form-input" placeholder="例如：循环结构练习" required /><label className="form-label" htmlFor="assignment-chapter">所属章节</label><select id="assignment-chapter" name="chapterId" className="form-input" defaultValue={chapters[0]?.id}>{chapters.map((chapter) => <option key={chapter.id} value={chapter.id}>{chapter.name}</option>)}</select><label className="form-label" htmlFor="assignment-description">作业说明</label><textarea id="assignment-description" name="description" className="answer-box small-answer" placeholder="写下学生需要完成的内容……" /><label className="form-label" htmlFor="assignment-deadline">截止时间（可选）</label><input id="assignment-deadline" name="deadline" className="form-input" type="datetime-local" /><div className="form-actions"><button type="button" className="secondary-button" onClick={onClose}>取消</button><button type="submit" className="primary-button">保存作业</button></div></Modal>; }
function CreateChapterModal({ onClose, onSubmit }: { onClose: () => void; onSubmit: (name: string) => void }) { const creatingClass = typeof window !== "undefined" && Boolean((window as Window & { __qktCreateClass?: boolean }).__qktCreateClass); return <Modal onClose={onClose}><div className="modal-header"><div><p className="eyebrow">{creatingClass ? "班级管理" : "课程内容"}</p><h2>{creatingClass ? "新建班级" : "创建章节"}</h2></div><button type="button" className="close-button" onClick={onClose}>×</button></div><label className="form-label" htmlFor="chapter-name">{creatingClass ? "班级名称" : "章节名称"}</label><input id="chapter-name" className="form-input" placeholder={creatingClass ? "例如：线性代数基础班" : "例如：第 4 章 函数"} required autoFocus />{creatingClass && <><label className="form-label" htmlFor="chapter-course-name">课程名称</label><input id="chapter-course-name" className="form-input" placeholder="例如：线性代数" /></>}<div className="form-actions"><button type="button" className="secondary-button" onClick={onClose}>取消</button><button type="button" className="primary-button" onClick={() => { const input = document.getElementById("chapter-name") as HTMLInputElement; if (input.value.trim()) onSubmit(input.value.trim()); }}>{creatingClass ? "创建班级" : "创建章节"}</button></div></Modal>; }
function JoinClassModal({ onClose, onSubmit }: { onClose: () => void; onSubmit: (code: string) => void }) { return <Modal onClose={onClose}><div className="modal-header"><div><p className="eyebrow">我的学习</p><h2>加入班级</h2></div><button type="button" className="close-button" onClick={onClose}>×</button></div><p className="modal-copy">输入老师提供的班级码即可加入课程。</p><label className="form-label" htmlFor="join-code">班级码</label><input id="join-code" className="form-input join-code-input" placeholder="例如：PY2026" autoFocus /><div className="form-actions"><button type="button" className="secondary-button" onClick={onClose}>取消</button><button type="button" className="primary-button" onClick={() => { const input = document.getElementById("join-code") as HTMLInputElement; onSubmit(input.value); }}>加入班级</button></div></Modal>; }
function GradeSubmissionModal({ submission, studentName, onClose, onSubmit }: { submission: Submission; studentName: string; onClose: () => void; onSubmit: (payload: GradePayload) => void }) { function submit(event: React.FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); onSubmit({ submissionId: submission.id, score: String(form.get("score") ?? ""), feedback: String(form.get("feedback") ?? "") }); } return <Modal onClose={onClose}><div className="modal-header"><div><p className="eyebrow">提交详情 · {studentName}</p><h2>查看并评分</h2></div><button type="button" className="close-button" onClick={onClose}>×</button></div><p className="form-label">学生回答</p><div className="answer-preview">{submission.content || "（学生未填写文字回答）"}</div><label className="form-label" htmlFor="score">分数（0-100）</label><input id="score" name="score" type="number" className="form-input" min="0" max="100" step="0.01" defaultValue={submission.score ?? ""} /><label className="form-label" htmlFor="feedback">教师评语</label><textarea id="feedback" name="feedback" className="answer-box small-answer" defaultValue={submission.feedback ?? ""} /><div className="form-actions"><button type="button" className="secondary-button" onClick={onClose}>取消</button><button type="submit" className="primary-button">保存评分</button></div></Modal>; }

function TeacherClassroom({ data, lesson, onRefresh }: { data: ClassroomData; lesson: LessonData; onRefresh: () => Promise<void> }) {
  const [prompt, setPrompt] = useState("");
  const [options, setOptions] = useState(["A", "B", "C", "D"]);
  const [chapterId, setChapterId] = useState(data.chapters.at(-1)?.id ?? "");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [draftSource, setDraftSource] = useState("");
  const [analyzing, setAnalyzing] = useState(false);
  const [aiMessage, setAiMessage] = useState("");
  const [watching, setWatching] = useState("");
  useEffect(() => {
    const saved = localStorage.getItem("ai-draft-question");
    if (!saved) return;
    try {
      const draft = JSON.parse(saved) as { prompt?: string; options?: string[]; sourceName?: string };
      if (draft.prompt) setPrompt(draft.prompt);
      if (Array.isArray(draft.options) && draft.options.length > 0) setOptions(draft.options);
      if (draft.sourceName) setDraftSource(draft.sourceName);
      localStorage.removeItem("ai-draft-question");
    } catch { localStorage.removeItem("ai-draft-question"); }
  }, []);
  async function analyzeMaterial(event: React.ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];
    event.target.value = "";
    if (!file || !chapterId) return;
    setAnalyzing(true); setAiMessage(""); setError("");
    try {
      const form = new FormData(); form.append("chapterId", chapterId); form.append("file", file);
      const uploadResponse = await fetch("/api/materials", { method: "POST", body: form });
      const uploadResult = await uploadResponse.json().catch(() => null) as { material?: { name?: string; type?: string }; error?: string } | null;
      if (!uploadResponse.ok) throw new Error(uploadResult?.error || "材料上传失败，请重试");
      const text = /\.(txt|md)$/i.test(file.name) ? await file.text().catch(() => "") : "";
      const aiResponse = await fetch("/api/ai/drafts", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ materialName: uploadResult?.material?.name ?? file.name, materialType: uploadResult?.material?.type ?? "FILE", text }) });
      const aiResult = await aiResponse.json().catch(() => null) as { draft?: AIDraft; error?: string } | null;
      if (!aiResponse.ok || !aiResult?.draft) throw new Error(aiResult?.error || "AI 识别失败，请稍后重试");
      const question = aiResult.draft.questions[0];
      if (question) { setPrompt(question.prompt); setOptions(question.options); }
      setDraftSource(aiResult.draft.sourceName); setAiMessage("材料已识别，题目草稿已填入下方。请先核对、修改，再点击“审核并发布题目”。");
    } catch (cause) { setAiMessage(cause instanceof Error ? cause.message : "材料处理失败，请重试"); }
    finally { setAnalyzing(false); }
  }
  async function start(action: "start" | "restart" = "start") {
    setBusy(true); setError("");
    try {
      const response = await fetch("/api/lessons", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action, chapterId }) });
      const result = await response.json().catch(() => null) as { error?: string } | null;
      if (!response.ok) throw new Error(result?.error || "开始课堂失败，请刷新后重试");
      await onRefresh();
    } catch (cause) { setError(cause instanceof Error ? cause.message : "开始课堂失败，请刷新后重试"); }
    finally { setBusy(false); }
  }
  async function publish(event: React.FormEvent) {
    event.preventDefault(); setBusy(true); setError("");
    try {
      const response = await fetch("/api/lessons", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "publish", prompt, options }) });
      const result = await response.json().catch(() => null) as { error?: string } | null;
      if (!response.ok) throw new Error(result?.error || "发布题目失败，请重试");
      setPrompt(""); setDraftSource(""); await onRefresh();
    } catch (cause) { setError(cause instanceof Error ? cause.message : "发布题目失败，请重试"); }
    finally { setBusy(false); }
  }
  async function end() {
    setBusy(true); setError("");
    try {
      const response = await fetch("/api/lessons", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "end" }) });
      const result = await response.json().catch(() => null) as { error?: string } | null;
      if (!response.ok) throw new Error(result?.error || "结束课堂失败，请重试");
      await onRefresh();
    } catch (cause) { setError(cause instanceof Error ? cause.message : "结束课堂失败，请重试"); }
    finally { setBusy(false); }
  }
  return <div className="page-stack"><div className="page-heading-row"><div><p className="breadcrumb">课堂互动 / {data.class.name}</p><h1>课堂运行</h1><p className="page-description">题目来自材料识别草稿；教师审核后才会发布给学生。</p></div><div className="classroom-actions"><select className="form-input chapter-select" aria-label="课堂章节" value={chapterId} onChange={(event) => setChapterId(event.target.value)} disabled={lesson.session?.status === "active"}>{data.chapters.map((chapter) => <option key={chapter.id} value={chapter.id}>{chapter.name}</option>)}</select>{lesson.session?.status === "active" ? <><Badge tone="green">课堂进行中</Badge><button type="button" className="secondary-button" onClick={() => start("restart")} disabled={busy}>重新开始体验</button></> : <button type="button" className="primary-button" onClick={() => start()} disabled={busy || !chapterId}>{busy ? "启动中…" : "开始课堂"}</button>}</div></div>{error && <div className="inline-error" role="alert">{error}</div>}{lesson.session?.status !== "active" ? <section className="content-section"><div className="empty-record">请选择本节课章节，然后点击“开始课堂”。</div></section> : <div className="classroom-grid"><section className="content-section"><SectionTitle title="发布课堂题目" description={draftSource ? "已载入材料“" + draftSource + "”的草稿，可继续修改" : "先导入材料，AI 会把识别出的题目填入下方。"} /><div className="ai-material-submit"><div><strong>导入题目材料并识别</strong><p>支持 PDF、PPT、Word、图片、TXT、Markdown；识别后仍需教师审核。</p></div><label className="secondary-button ai-upload-button">{analyzing ? "识别中…" : "选择材料文件"}<input type="file" className="visually-hidden" accept=".pdf,.ppt,.pptx,.doc,.docx,.png,.jpg,.jpeg,.txt,.md" onChange={analyzeMaterial} disabled={analyzing} /></label></div>{aiMessage && <div className={aiMessage.includes("失败") ? "inline-error" : "feedback-box"} role="status">{aiMessage}</div>}<form onSubmit={publish}><label className="form-label" htmlFor="activity-prompt">题目</label><textarea id="activity-prompt" className="answer-box small-answer" value={prompt} onChange={(event) => setPrompt(event.target.value)} placeholder="上传材料后会自动填入，也可以直接在这里输入题目" required /><label className="form-label">选项</label>{options.map((option, index) => <input key={index} className="form-input activity-option" value={option} onChange={(event) => setOptions((current) => current.map((item, itemIndex) => itemIndex === index ? event.target.value : item))} aria-label={"选项 " + (index + 1)} />)}<div className="form-actions"><button type="submit" className="primary-button" disabled={busy}>{busy ? "发布中…" : "审核并发布题目"}</button></div></form></section><section className="content-section"><SectionTitle title="活动结果" description="提交人数和选项分布会实时更新。" />{lesson.activities.length === 0 && <div className="empty-record">还没有发布活动。</div>}{lesson.activities.map((activity) => <div className="activity-result" key={activity.id}><div className="task-title-line"><strong>{activity.prompt}</strong><Badge>{activity.responses} 人作答</Badge></div><div className="option-distribution">{activity.options.map((option) => <><div className="distribution-row" key={option}><span>{option}</span><div className="distribution-bar"><i style={{ width: String(activity.responses ? ((activity.distribution[option] ?? 0) / activity.responses) * 100 : 0) + "%" }} /></div><b>{activity.distribution[option] ?? 0}</b><button type="button" className="text-button response-view-button" onClick={() => setWatching(watching === activity.id + ":" + option ? "" : activity.id + ":" + option)}>{watching === activity.id + ":" + option ? "收起" : "查看名单"}</button></div>{watching === activity.id + ":" + option && <div className="respondent-list">{(activity.respondents?.[option] ?? []).length ? (activity.respondents?.[option] ?? []).map((name) => <span key={name}>{name}</span>) : <span>暂时没有学生选择此项</span>}</div>}</>)} </div></div>)}<button type="button" className="secondary-button end-class-button" onClick={end} disabled={busy}>结束课堂</button></section></div>}</div>;
}

function StudentClassroom({ lesson, onRefresh }: { lesson: LessonData; onRefresh: () => Promise<void> }) { const activity = lesson.activities.at(-1); const [answer, setAnswer] = useState(""); const [sent, setSent] = useState(false); const [message, setMessage] = useState(""); async function respond() { if (!activity || !answer) return; setSent(true); setMessage(""); try { const response = await fetch("/api/lessons", { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ activityId: activity.id, studentId: "student_1", answer }) }); const result = await response.json().catch(() => null) as { error?: string } | null; if (!response.ok) throw new Error(result?.error || "提交失败，请重试"); setMessage("答案已提交，教师端可以看到你的作答。"); await onRefresh().catch(() => undefined); } catch (cause) { setSent(false); setMessage(cause instanceof Error ? cause.message : "提交失败，请重试"); } } return <div className="page-stack"><div className="page-heading-row"><div><p className="breadcrumb">课堂互动 / 学生作答</p><h1>课堂互动</h1><p className="page-description">跟随老师的课堂活动提交答案。</p></div>{lesson.session?.status === "active" ? <Badge tone="green">课堂进行中</Badge> : <Badge tone="gray">暂无课堂</Badge>}</div>{!lesson.session || lesson.session.status !== "active" ? <section className="content-section"><div className="empty-record">老师还没有开始课堂，请稍后再来。</div></section> : !activity ? <section className="content-section"><div className="empty-record">课堂已开始，等待老师发布第一道题。</div></section> : <section className="assignment-detail"><div className="detail-heading"><div><span className="eyebrow">选择题</span><h2>{activity.prompt}</h2></div><Badge>{activity.responses} 人已作答</Badge></div><div className="choice-list">{activity.options.map((option) => <label className={`choice-item ${answer === option ? "choice-selected" : ""}`} key={option}><input type="radio" name="class-choice" value={option} checked={answer === option} onChange={() => setAnswer(option)} /><span>{option}</span></label>)}</div><div className="form-actions"><button type="button" className="primary-button" disabled={!answer || sent} onClick={respond}>{sent ? "已提交" : "提交答案"}</button></div>{message && <div className={sent ? "feedback-box" : "inline-error"} role="status">{message}</div>}</section>}</div>; }
